CREATE TYPE "AccountKind" AS ENUM ('ASSET','LIABILITY','EQUITY','REVENUE','EXPENSE');
CREATE TYPE "AttemptStatus" AS ENUM ('ACTIVE','SUBMITTED','RESET');
CREATE TABLE "case_templates" ("id" UUID PRIMARY KEY, "slug" TEXT UNIQUE NOT NULL, "title" TEXT NOT NULL, "student_scenario" JSONB NOT NULL, "instructor_data" JSONB NOT NULL, "created_at" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "template_accounts" ("id" UUID PRIMARY KEY, "template_id" UUID NOT NULL REFERENCES "case_templates"("id") ON DELETE RESTRICT, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "kind" "AccountKind" NOT NULL, UNIQUE("template_id","id"), UNIQUE("template_id","code"));
CREATE TABLE "template_documents" ("id" UUID PRIMARY KEY, "template_id" UUID NOT NULL REFERENCES "case_templates"("id") ON DELETE RESTRICT, "title" TEXT NOT NULL, "student_content" JSONB NOT NULL, "instructor_data" JSONB NOT NULL, "unlock_after_action" INTEGER NOT NULL CHECK ("unlock_after_action">0), UNIQUE("template_id","id"));
CREATE TABLE "student_attempts" ("id" UUID PRIMARY KEY, "student_id" TEXT NOT NULL, "template_id" UUID NOT NULL REFERENCES "case_templates"("id") ON DELETE RESTRICT, "generation" INTEGER NOT NULL DEFAULT 1, "status" "AttemptStatus" NOT NULL DEFAULT 'ACTIVE', "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE("student_id","template_id","generation"));
CREATE INDEX "student_attempts_student_id_id_idx" ON "student_attempts"("student_id","id");
CREATE FUNCTION reject_attempt_identity_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'attempt identity is immutable'; END $$;
CREATE TRIGGER student_attempt_identity_immutable BEFORE UPDATE OF student_id,template_id,generation ON "student_attempts" FOR EACH ROW EXECUTE FUNCTION reject_attempt_identity_mutation();
CREATE TABLE "attempt_accounts" ("id" UUID PRIMARY KEY, "attempt_id" UUID NOT NULL REFERENCES "student_attempts"("id") ON DELETE CASCADE, "source_template_account_id" UUID NOT NULL REFERENCES "template_accounts"("id") ON DELETE RESTRICT, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "kind" "AccountKind" NOT NULL, UNIQUE("attempt_id","id"), UNIQUE("attempt_id","code"));
CREATE FUNCTION assert_attempt_account_template() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM student_attempts attempt JOIN template_accounts source ON source.id=NEW.source_template_account_id WHERE attempt.id=NEW.attempt_id AND attempt.template_id=source.template_id) THEN RAISE EXCEPTION 'account source is outside the attempt template'; END IF; RETURN NEW; END $$;
CREATE TRIGGER attempt_account_template_match BEFORE INSERT OR UPDATE OF attempt_id,source_template_account_id ON "attempt_accounts" FOR EACH ROW EXECUTE FUNCTION assert_attempt_account_template();
CREATE TABLE "journal_entries" ("id" UUID PRIMARY KEY, "attempt_id" UUID NOT NULL REFERENCES "student_attempts"("id") ON DELETE CASCADE, "description" TEXT NOT NULL, "occurred_on" DATE NOT NULL, "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE("attempt_id","id"));
CREATE TABLE "journal_lines" ("id" UUID PRIMARY KEY, "entry_id" UUID NOT NULL, "attempt_id" UUID NOT NULL, "attempt_account_id" UUID NOT NULL, "debit_cents" BIGINT NOT NULL DEFAULT 0, "credit_cents" BIGINT NOT NULL DEFAULT 0, CHECK (("debit_cents">0 AND "credit_cents"=0) OR ("credit_cents">0 AND "debit_cents"=0)), FOREIGN KEY("attempt_id","entry_id") REFERENCES "journal_entries"("attempt_id","id") ON DELETE CASCADE, FOREIGN KEY("attempt_id","attempt_account_id") REFERENCES "attempt_accounts"("attempt_id","id") ON DELETE RESTRICT);
CREATE INDEX "journal_lines_entry_id_idx" ON "journal_lines"("entry_id");
CREATE TABLE "attempt_actions" ("id" UUID PRIMARY KEY, "attempt_id" UUID NOT NULL REFERENCES "student_attempts"("id") ON DELETE CASCADE, "sequence" INTEGER NOT NULL, "kind" TEXT NOT NULL, "detail" JSONB NOT NULL DEFAULT '{}', "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE("attempt_id","sequence"));
CREATE FUNCTION reject_template_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'case template source is immutable'; END $$;
CREATE TRIGGER case_templates_immutable BEFORE UPDATE OR DELETE ON "case_templates" FOR EACH ROW EXECUTE FUNCTION reject_template_mutation();
CREATE TRIGGER template_accounts_immutable BEFORE UPDATE OR DELETE ON "template_accounts" FOR EACH ROW EXECUTE FUNCTION reject_template_mutation();
CREATE TRIGGER template_documents_immutable BEFORE UPDATE OR DELETE ON "template_documents" FOR EACH ROW EXECUTE FUNCTION reject_template_mutation();
CREATE FUNCTION assert_entry_balanced() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE target UUID; d BIGINT; c BIGINT; n BIGINT; BEGIN FOR target IN SELECT DISTINCT candidate FROM unnest(ARRAY[CASE WHEN TG_OP<>'DELETE' THEN NEW.entry_id END,CASE WHEN TG_OP<>'INSERT' THEN OLD.entry_id END]) candidate WHERE candidate IS NOT NULL LOOP IF EXISTS (SELECT 1 FROM journal_entries WHERE id=target) THEN SELECT COALESCE(SUM(debit_cents),0),COALESCE(SUM(credit_cents),0),COUNT(*) INTO d,c,n FROM journal_lines WHERE entry_id=target; IF n<2 OR d<>c THEN RAISE EXCEPTION 'unbalanced journal entry'; END IF; END IF; END LOOP; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER journal_entry_balanced AFTER INSERT OR UPDATE OR DELETE ON "journal_lines" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION assert_entry_balanced();
CREATE FUNCTION assert_new_entry_balanced() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE d BIGINT; c BIGINT; n BIGINT; BEGIN SELECT COALESCE(SUM(debit_cents),0),COALESCE(SUM(credit_cents),0),COUNT(*) INTO d,c,n FROM journal_lines WHERE entry_id=NEW.id; IF n<2 OR d<>c THEN RAISE EXCEPTION 'unbalanced journal entry'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER journal_entry_requires_lines AFTER INSERT OR UPDATE OF id,attempt_id ON "journal_entries" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION assert_new_entry_balanced();
